package pre05mini;
public abstract class Account {protected final String accountNumber;protected String ownerName;protected long balance;public Account(String n,String o,long b){accountNumber=n;ownerName=o;balance=b;}public long getBalance(){return balance;}public abstract double interestRate();public abstract boolean canWithdraw(long amount);public boolean withdraw(long amount){if(amount>0&&canWithdraw(amount)){balance-=amount;return true;}return false;}public void deposit(long amount){if(amount>0)balance+=amount;}public String toString(){return accountNumber+" | "+ownerName+" | Rs."+balance;}}
